        /// <summary>
        /// Determines if a property name matches '^x-'
        /// for the pattern property producing the type
        /// <see cref="Corvus.Json.JsonSchema.OpenApi20.OpenApiDocument.VendorExtension"/>.
        /// </summary>
        public static bool MatchesPatternVendorExtension(in JsonObjectProperty property) => property.Name.IsMatch(CorvusValidation.PatternProperties);

        /// <summary>
        /// Gets an instance of the type
        /// <see cref="Corvus.Json.JsonSchema.OpenApi20.OpenApiDocument.VendorExtension"/>
        /// if the property name matches '^x-'.
        /// </summary>
        public static bool TryAsPatternVendorExtension(in JsonObjectProperty property, out Corvus.Json.JsonSchema.OpenApi20.OpenApiDocument.VendorExtension result)
        {
            if (property.Name.IsMatch(CorvusValidation.PatternProperties))
            {
                result = property.Value.As<Corvus.Json.JsonSchema.OpenApi20.OpenApiDocument.VendorExtension>();
                return result.IsValid();
            }

            result = Corvus.Json.JsonSchema.OpenApi20.OpenApiDocument.VendorExtension.Undefined;
            return false;
        }

        /// <summary>
        /// Visits properties matched by generated pattern property helpers.
        /// </summary>
        /// <typeparam name="TState">The visitor state type.</typeparam>
        public interface IPatternPropertyVisitor<TState>
        {
            /// <summary>
            /// Visits a property matching '^x-'.
            /// </summary>
            bool VisitPatternVendorExtension(in JsonPropertyName name, in Corvus.Json.JsonSchema.OpenApi20.OpenApiDocument.VendorExtension value, ref TState state);

            /// <summary>
            /// Visits a property that did not match any generated pattern property.
            /// </summary>
            bool VisitUnmatched(in JsonPropertyName name, in JsonAny value, ref TState state);
        }

        /// <summary>
        /// Matches each property against the generated pattern properties and dispatches to a visitor.
        /// </summary>
        /// <typeparam name="TState">The visitor state type.</typeparam>
        /// <typeparam name="TVisitor">The visitor type.</typeparam>
        /// <param name="state">The visitor state.</param>
        /// <param name="visitor">The visitor to call for each matched or unmatched property.</param>
        /// <param name="shortCircuit">If <see langword="true"/>, only the first matching pattern is visited for each property.</param>
        /// <returns><see langword="true"/> if every visitor call returned <see langword="true"/>, otherwise <see langword="false"/>.</returns>
        public bool MatchPatternProperties<TState, TVisitor>(ref TState state, TVisitor visitor, bool shortCircuit = false)
            where TVisitor : IPatternPropertyVisitor<TState>
        {
            foreach (JsonObjectProperty property in EnumerateObject())
            {
                JsonPropertyName propertyName = property.Name;
                bool matched = false;

                if (MatchesPatternVendorExtension(in property))
                {
                    matched = true;
                    Corvus.Json.JsonSchema.OpenApi20.OpenApiDocument.VendorExtension typedValue = property.Value.As<Corvus.Json.JsonSchema.OpenApi20.OpenApiDocument.VendorExtension>();
                    if (!visitor.VisitPatternVendorExtension(in propertyName, in typedValue, ref state))
                    {
                        return false;
                    }

                    if (shortCircuit)
                    {
                        continue;
                    }
                }

                if (!matched)
                {
                    JsonAny unmatchedValue = property.Value;
                    if (!visitor.VisitUnmatched(in propertyName, in unmatchedValue, ref state))
                    {
                        return false;
                    }
                }
            }

            return true;
        }

